-- =============================================================================
-- 时区数据字典初始化脚本
-- 字典类型：sys_timezone
-- 数据来源：Node.js Intl.supportedValuesOf('timeZone') / IANA Time Zone Database
-- 时差采样时间：2026-06-13T00:00:00Z，包含夏令时影响。
-- =============================================================================

START TRANSACTION;

VALUES ('时区', 'sys_timezone', 'system', 1, 1, 1, 'IANA 时区列表，包含 UTC 时差，供商户时区下拉使用', 'system', 'system', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3), 0)
ON DUPLICATE KEY UPDATE
    dict_name = VALUES(dict_name),
    biz_domain = VALUES(biz_domain),
    system_builtin = VALUES(system_builtin),
    editable = VALUES(editable),
    status = VALUES(status),
    remark = VALUES(remark),
    updated_by = VALUES(updated_by),
    updated_at = CURRENT_TIMESTAMP(3),
    deleted = 0;

ON DUPLICATE KEY UPDATE
    dict_label = VALUES(dict_label),
    parent_value = VALUES(parent_value),
    dict_sort = VALUES(dict_sort),
    list_class = VALUES(list_class),
    extra_json = VALUES(extra_json),
    is_default = VALUES(is_default),
    status = VALUES(status),
    remark = VALUES(remark),
    updated_by = VALUES(updated_by),
    updated_at = CURRENT_TIMESTAMP(3),
    deleted = 0;

COMMIT;
